/*
 * @lc app=leetcode id=2983 lang=kotlin
 *
 * [2983] Palindrome Rearrangement Queries
 */

class Solution { fun canMakePalindromeQueries(s: String, queries: Array<IntArray>): BooleanArray = (s.length / 2).let { half -> Array(half + 1) { IntArray(26) }.let { pref1 -> Array(half + 1) { IntArray(26) }.let { pref2 -> IntArray(half + 1).let { diff -> (0 until half).forEach { i -> (0 until 26).forEach { c -> pref1[i + 1][c] = pref1[i][c].also { pref2[i + 1][c] = pref2[i][c] } }.also { pref1[i + 1][s[i] - 'a']++ }.also { pref2[i + 1][s[s.length - 1 - i] - 'a']++ }.also { diff[i + 1] = diff[i] + if (s[i] != s[s.length - 1 - i]) 1 else 0 } }.let { if ((0 until 26).any { c -> pref1[half][c] != pref2[half][c] }) BooleanArray(queries.size) else BooleanArray(queries.size) { qIdx -> queries[qIdx][0].let { l1 -> queries[qIdx][1].let { r1 -> (s.length - 1 - queries[qIdx][3]).let { l2 -> (s.length - 1 - queries[qIdx][2]).let { r2 -> { l: Int, r: Int -> if (l <= r) diff[r + 1] - diff[l] else 0 }.let { getDiff -> getDiff(0, half - 1) == getDiff(l1, r1) + getDiff(l2, r2) - getDiff(maxOf(l1, l2), minOf(r1, r2)) && (0 until 26).all { c -> (if (l1 <= r1) pref1[r1 + 1][c] - pref1[l1][c] else 0) >= (if (l1 <= minOf(r1, l2 - 1)) pref2[minOf(r1, l2 - 1) + 1][c] - pref2[l1][c] else 0) + (if (maxOf(l1, r2 + 1) <= r1) pref2[r1 + 1][c] - pref2[maxOf(l1, r2 + 1)][c] else 0) && (if (l2 <= r2) pref2[r2 + 1][c] - pref2[l2][c] else 0) >= (if (l2 <= minOf(r2, l1 - 1)) pref1[minOf(r2, l1 - 1) + 1][c] - pref1[l2][c] else 0) + (if (maxOf(l2, r1 + 1) <= r2) pref1[r1 + 1][c] - pref1[maxOf(l2, r1 + 1)][c] else 0) } } } } } } } } } } } }